    58  bool CheckTag(uint32_t tag_value) {
    59    for (unsigned i = 0; i < 4; ++i) {
    60      const uint32_t check = tag_value & 0xff;
    61      if (check < 32 || check > 126) {
    62        return false;  // non-ASCII character found.
    63      }
    64      tag_value >>= 8;
    65    }
    66    return true;
    67  }
